type Status = 'active' | 'pending' | 'review' | 'secure' | 'verified' | 'risk' | 'neutral';
type LegacyAction = 'Transfer' | 'Preserve' | 'Notify' | 'Delete' | 'Do Not Share' | 'Manual Review';
type User = { id: string; name: string; email: string; role: string; workspace: string };
type Asset = { id: string; name: string; provider: string; type: string; status: Status; sensitivity: string; lastVerified: string; beneficiaryId: string; tags: string[]; description: string; action: LegacyAction };
type Beneficiary = { id: string; name: string; relation: string; email: string; status: Status; verification: string; note: string };
type Policy = { id: string; name: string; trigger: string; status: Status; assets: string[]; primary: string; fallback: string; threshold: string; description: string; updated: string };
type VaultItem = { id: string; title: string; type: string; status: Status; updated: string; detail: string };
type VerificationEvent = { id: string; beneficiaryId: string; check: string; status: Status; time: string; detail: string };
type AuditEvent = { id: string; action: string; subject: string; actor: string; time: string; tone: Status; detail: string };
type Notification = { id: string; title: string; detail: string; read: boolean; time: string };
type SecurityFinding = { id: string; title: string; detail: string; severity: 'good' | 'warn' | 'risk'; action: string };
type DataState = { assets: Asset[]; beneficiaries: Beneficiary[]; policies: Policy[]; vault: VaultItem[]; audit: AuditEvent[]; readiness?: { configuredAssets: number; totalAssets: number; assignedBeneficiaries: number; totalBeneficiaries: number; completePolicies: number; totalPolicies: number; vaultCoverage: number } };
type ToastItem = { id: string; title: string; detail?: string };
type ModalKind = 'asset' | 'beneficiary' | 'vault' | 'policy' | 'confirm' | 'command' | null;

