function readState(): DataState {
  try {
    const saved = localStorage.getItem('deadlock-state');
    if (!saved) return seedData;
    const parsed = JSON.parse(saved) as Partial<DataState>;
    return { ...seedData, ...parsed, readiness: parsed.readiness ?? seedData.readiness };
  } catch {
    return seedData;
  }
}

function StatusPill({ status }: { status: Status }) {
  const labels: Record<Status, string> = { active: 'Active', pending: 'Pending', review: 'Review', secure: 'Sealed', verified: 'Verified', risk: 'Risk', neutral: 'Neutral' };
  return <span className={`status status-${status}`} data-testid={`status-${status}`}>{labels[status]}</span>;
}

function Logo({ link = true }: { link?: boolean }) {
  const content = <><span className="brand-mark"><LockKeyhole size={15} /></span><span><span className="brand-word">DEADLOCK</span><span className="brand-sub">LEGACY SECURITY</span></span></>;
  return link ? <Link href="/" className="brand" data-testid="link-logo">{content}</Link> : <div className="brand">{content}</div>;
}

function Modal({ title, description, onClose, children, wide = false }: { title: string; description?: string; onClose: () => void; children: ReactNode; wide?: boolean }) {
  return <div className="modal-backdrop" role="dialog" aria-modal="true" onMouseDown={(event) => { if (event.currentTarget === event.target) onClose(); }}>
    <div className={`modal ${wide ? 'command-modal' : ''}`}>
      <div className="modal-head"><div><div className="modal-title">{title}</div>{description && <div className="modal-copy">{description}</div>}</div><button className="icon-btn" onClick={onClose} aria-label="Close dialog" data-testid="button-close-dialog"><X size={15} /></button></div>
      <div className="modal-body">{children}</div>
    </div>
  </div>;
}

function EmptyState({ icon: Icon, title, children, action }: { icon: typeof Archive; title: string; children: ReactNode; action?: ReactNode }) {
  return <div className="empty"><div className="empty-icon"><Icon size={17} /></div><div className="empty-title">{title}</div><p>{children}</p>{action}</div>;
}

